import{Z as t,e as a,f as r,a0 as i}from"./chunks/framework.DmpHOl9T.js";const p=JSON.parse('{"title":"Creating Your First Form","description":"","frontmatter":{},"headers":[],"relativePath":"get-started/creating-your-first-form.md","filePath":"get-started/creating-your-first-form.md","lastUpdated":null}'),s={name:"get-started/creating-your-first-form.md"};function o(n,e,d,c,m,l){return a(),r("div",null,[...e[0]||(e[0]=[i('<h1 id="creating-your-first-form" tabindex="-1">Creating Your First Form <a class="header-anchor" href="#creating-your-first-form" aria-label="Permalink to &quot;Creating Your First Form&quot;">​</a></h1><p>You&#39;ll create a contact form, show it on a page and check a submitted message. Start with Formie installed, permission to create forms, a Twig template you can edit and working email settings in Craft.</p><p>Create a form in Formie named Contact Form with the handle <code>contactForm</code>. In the <a href="docs:forms/form-builder" target="_blank" rel="noreferrer">form builder</a>, add an Email Address field and a Multi-Line Text field for the message. Make the fields required so the first test can also check validation. Save the form.</p><p>Configure an <a href="docs:forms/email-notifications" target="_blank" rel="noreferrer">email notification</a> for an address you can read. Use a sender address permitted by your mail service; use the submitted email as Reply-To when you want to reply to the visitor. Include the submitted fields in the notification body and save it.</p><p>In the Twig template for your contact page, render the saved form:</p><div class="language-twig vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">twig</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{{ craft.formie.renderForm(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;contactForm&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">) }}</span></span></code></pre></div><p>Open the page in a visitor browser. Submit the empty form to check the required fields, then enter an email and a recognisable message and submit again. Check the success response, the saved submission in Formie and the notification in the recipient&#39;s inbox.</p><p>If the submission exists but the email is missing, inspect Craft&#39;s queue and mail settings. These are separate stages: storing a submission does not prove that an email reached the recipient. Once the complete path works, <a href="docs:templates/rendering-forms" target="_blank" rel="noreferrer">Rendering Forms</a> covers output options and customisation.</p>',8)])])}const f=t(s,[["render",o]]);export{p as __pageData,f as default};
